    instance_norm_kernel<<<num_blocks, block_size>>>(x.data_ptr<float>(), mean_ptr, var_ptr, out.data_ptr<float>(), size);

    cudaFree(mean_ptr);
    cudaFree(var_ptr);

    return out;
}
